  res.json([
    { id: 1, name: 'Alice' },  // Don't expose emails without auth
    { id: 2, name: 'Bob' },
  ]);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

